import assert from 'node:assert/strict';
import { createHash, createPublicKey, verify } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
const directory = resolve(import.meta.dirname, '..');
const receipts = [];
for (const name of ['baseline', 'candidate']) {
  const raw = await readFile(resolve(directory, `${name}-sustained-hosted.json`));
  const campaign = JSON.parse(raw);
  const publicKey = Buffer.from(campaign.publicKeyHex, 'hex');
  assert.equal(publicKey.length, 1952);
  const key = createPublicKey({key: Buffer.concat([Buffer.from('308207b2300b0609608648016503040312038207a100','hex'),publicKey]), format:'der', type:'spki'});
  assert.equal(key.asymmetricKeyType, 'ml-dsa-65');
  const results = [];
  for (const row of campaign.requests) {
    if (row.state !== 'succeeded') continue;
    const message = Buffer.from(row.messageHex, 'hex');
    const signature = Buffer.from(row.signatureHex, 'hex');
    assert.equal(message.length,32);
    assert.equal(signature.length,3309);
    assert.equal(verify(null,message,key,signature),true);
    const changedMessage = Buffer.from(message);
    changedMessage[0] ^= 1;
    assert.equal(verify(null,changedMessage,key,signature),false);
    const changedSignature = Buffer.from(signature);
    changedSignature[0] ^= 1;
    assert.equal(verify(null,message,key,changedSignature),false);
    results.push({operation:Buffer.from(row.operation).toString('hex'),verified:true,alteredMessageRejected:true,alteredSignatureRejected:true});
  }
  assert.equal(results.length,name==='baseline'?12:24);
  receipts.push({campaign:name,sha256:createHash('sha256').update(raw).digest('hex'),node:process.version,openssl:process.versions.openssl,context:'Empty, per retained runner',results});
}
await writeFile(resolve(import.meta.dirname,'signature-verification.json'),JSON.stringify(receipts,null,2)+'\n');
console.log(JSON.stringify(receipts.map(row=>({campaign:row.campaign,verified:row.results.length,negativeChecks:row.results.length*2}))));

